"use strict";(self.webpackChunkwebsite=self.webpackChunkwebsite||[]).push([[6903],{57455:(t,a,e)=>{e.r(a),e.d(a,{TutorialDirectory:()=>c,assets:()=>l,contentTitle:()=>i,default:()=>u,frontMatter:()=>s,metadata:()=>n,toc:()=>d});const n=JSON.parse('{"id":"intro","title":"Tutorials Directory","description":"Zero-to-Hero (Start Here)","source":"@site/docs/intro.mdx","sourceDirName":".","slug":"/intro","permalink":"/MARSLib/docs/intro","draft":false,"unlisted":false,"editUrl":"https://github.com/MARSProgramming/MARSLib/tree/master/website/docs/intro.mdx","tags":[],"version":"current","sidebarPosition":1,"frontMatter":{"id":"intro","sidebar_position":1,"title":"Tutorials Directory","slug":"/intro"},"sidebar":"tutorialSidebar","next":{"title":"Tutorials","permalink":"/MARSLib/docs/category/tutorials"}}');var r=e(74848),o=e(28453);const s={id:"intro",sidebar_position:1,title:"Tutorials Directory",slug:"/intro"},i=void 0,l={},c=()=>(0,r.jsx)("div",{dangerouslySetInnerHTML:{__html:'\n<main class="container" style="padding-top: 40px; padding-bottom: 80px;">\n  <div style="text-align: center; margin-bottom: 60px;">\n    <h1>Recruit Training</h1>\n    <p style="font-size: 1.25rem; color: var(--text-secondary); max-width: 700px; margin: 0 auto;">Step-by-step guides for students and mentors to master the MARSLib framework architecture.</p>\n  </div>\n\n  <div style="margin-top: 60px; border-bottom: 1px solid var(--border); padding-bottom: 16px;">\n    <h2 style="font-family: \'Orbitron\', sans-serif; color: var(--mars-red);">Zero-to-Hero (Start Here)</h2>\n    <p style="color: var(--text-secondary);">An absolute beginner\'s tutorial track covering FRC basics, hardware, and WPILib Command-based concepts.</p>\n  </div>\n  <div class="tutorial-grid" style="padding: 40px 0;">\n    <a href="/MARSLib/docs/tutorials/zero-to-hero/landscape" class="tutorial-card">\n      <span class="card-tag">SOFTWARE</span>\n      <h3>The Dev Ecosystem</h3>\n      <p>Git version control, Gradle dependencies, and the WPILib FRC tools.</p>\n    </a>\n    \n    <a href="/MARSLib/docs/tutorials/zero-to-hero/hardware" class="tutorial-card">\n      <span class="card-tag">HARDWARE</span>\n      <h3>The Hardware Paradigm</h3>\n      <p>The RoboRIO brain, CAN bus topology, FMS Radio connections, and power shedding.</p>\n    </a>\n\n    <a href="/MARSLib/docs/tutorials/zero-to-hero/command-based" class="tutorial-card">\n      <span class="card-tag">ARCHITECTURE</span>\n      <h3>Command-Based Setup</h3>\n      <p>How Subsystems, Commands, and the 20ms Control Loop physically evaluate code without crashing.</p>\n    </a>\n\n    <a href="/MARSLib/docs/tutorials/zero-to-hero/control-basics" class="tutorial-card">\n      <span class="card-tag">MATH</span>\n      <h3>Control Theory Crash Course</h3>\n      <p>Master PID tuning visually, overcome Gravity with Feedforwards, and learn the dangers of mechanical oscillation.</p>\n    </a>\n  </div>\n\n  <div style="margin-top: 60px; border-bottom: 1px solid var(--border); padding-bottom: 16px;">\n    <h2 style="font-family: \'Orbitron\', sans-serif; color: var(--mars-red);">Onboarding &amp; Getting Started</h2>\n    <p style="color: var(--text-secondary);">Essential setup and telemetry mastery for new recruits.</p>\n  </div>\n  <div class="tutorial-grid" style="padding: 40px 0;">\n    <a href="/MARSLib/docs/tutorials/setup/getting-started" class="tutorial-card">\n      <span class="card-tag">ENVIRONMENT</span>\n      <h3>Software Setup &amp; Git</h3>\n      <p>Install Git, WPILib, and clone the MARSLib framework repository to your machine. Set up the GitHub PAT for the log autouploader.</p>\n    </a>\n    \n    <a href="/MARSLib/docs/tutorials/setup/telemetry" class="tutorial-card">\n      <span class="card-tag">TELEMETRY</span>\n      <h3>AdvantageKit &amp; Scope</h3>\n      <p>Master log replay, visualize Swerve in 3D, configure NetworkTables, and import MARS custom layout templates.</p>\n    </a>\n\n    <a href="/MARSLib/docs/tutorials/setup/ci" class="tutorial-card">\n      <span class="card-tag">PIPELINE</span>\n      <h3>Intro to CI/CD &amp; Testing</h3>\n      <p>Understand how Continuous Integration automatically tests, formats, and verifies our robot code before it ever touches the field.</p>\n    </a>\n  </div>\n\n  <div style="margin-top: 20px; border-bottom: 1px solid var(--border); padding-bottom: 16px;">\n    <h2 style="font-family: \'Orbitron\', sans-serif; color: var(--mars-red);">Framework Mastery</h2>\n    <p style="color: var(--text-secondary);">Advanced architecture guides and physics implementations.</p>\n  </div>\n  <div class="tutorial-grid" style="padding-top: 40px;">\n    <a href="/MARSLib/docs/tutorials/framework/io-layer" class="tutorial-card">\n      <span class="card-tag">CORE ARCHITECTURE</span>\n      <h3>The IO Layer Pattern</h3>\n      <p>Learn why we separate hardware from logic and how to implement the AdvantageKit pattern for bit-perfect log replay.</p>\n    </a>\n\n    <a href="/MARSLib/docs/tutorials/framework/swerve" class="tutorial-card">\n      <span class="card-tag">DRIVETRAIN</span>\n      <h3>Swerve Drive Persistence</h3>\n      <p>Configure Phoenix 6 modules, implement 250Hz high-frequency odometry, and tune your drift compensation.</p>\n    </a>\n\n    <a href="/MARSLib/docs/tutorials/framework/state-machines" class="tutorial-card">\n      <span class="card-tag">LOGIC & CONTROL</span>\n      <h3>Crowning States</h3>\n      <p>Use MARSStateMachine to coordinate complex mechanisms and visualize live flowcharts in AdvantageScope.</p>\n    </a>\n\n    <a href="/MARSLib/docs/tutorials/framework/sotm" class="tutorial-card">\n      <span class="card-tag">ADVANCED MATH</span>\n      <h3>Elite Shooting (SOTM)</h3>\n      <p>Master the iterative physics solver for shooting fuel balls while pulling high-speed swerve maneuvers.</p>\n    </a>\n\n    <a href="/MARSLib/docs/tutorials/framework/simulation" class="tutorial-card">\n      <span class="card-tag">VIRTUAL ROBOT &amp; TESTING</span>\n      <h3>Physics-First Dev &amp; Testing</h3>\n      <p>Leverage Dyn4j to test your robot code offline. Spawn fuel balls, test collisions, and write deterministic JUnit CI/CD tests.</p>\n    </a>\n\n    <a href="/MARSLib/docs/tutorials/framework/vision" class="tutorial-card">\n      <span class="card-tag">LOCALIZATION</span>\n      <h3>Vision Fusion & Filtation</h3>\n      <p>Explore strict hallucination rejection filters, Megatag confidence scaling, and hardware latency compensation.</p>\n    </a>\n\n    <a href="/MARSLib/docs/tutorials/framework/control-theory" class="tutorial-card">\n      <span class="card-tag">KINEMATICS</span>\n      <h3>Control Theory Mastery</h3>\n      <p>Move past basic PID. Demystify feedforwards, state space models, discrete math, and continuous SysId tuning.</p>\n    </a>\n\n    <a href="/MARSLib/docs/tutorials/framework/sysid" class="tutorial-card">\n      <span class="card-tag">CHARACTERIZATION</span>\n      <h3>System Identification</h3>\n      <p>Stop guessing PID constants. Automate your characterization using WPILib SysId to generate perfect constants mathematically.</p>\n    </a>\n  </div>\n\n  <div style="margin-top: 80px; padding-top: 40px; border-top: 1px solid var(--border); text-align: center;">\n    <h2 style="font-family: \'Orbitron\', sans-serif; font-size: 2.5rem; color: var(--mars-red); margin-bottom: 16px; font-weight: 900; letter-spacing: 0.1em;">THE ELITE PLAYBOOK</h2>\n    <p style="color: var(--text-secondary); max-width: 700px; margin: 0 auto 40px auto;">Architectural strategies covering zero-allocation deterministic engineering, dynamic system voltage scaling, and safe framework mining.</p>\n  </div>\n\n  <div class="tutorial-grid" style="padding-top: 0;">\n    <a href="/MARSLib/docs/tutorials/elite/zero-allocation" class="tutorial-card">\n      <span class="card-tag">DETERMINISM</span>\n      <h3>Zero-Allocation Systems</h3>\n      <p>Eliminate JVM Garbage Collection spikes entirely using pre-allocated Ephemeral Structs and mutable proxy references.</p>\n    </a>\n\n    <a href="/MARSLib/docs/tutorials/elite/power-shedding" class="tutorial-card">\n      <span class="card-tag">ELECTRICAL</span>\n      <h3>Dynamic Power Shedding</h3>\n      <p>Configure MARSPowerManager to actively monitor battery voltage and throttle non-essential mechanism ceilings.</p>\n    </a>\n\n    <a href="/MARSLib/docs/tutorials/elite/code-mining" class="tutorial-card">\n      <span class="card-tag">FRAMEWORK</span>\n      <h3>Architecture Mining</h3>\n      <p>How we leverage AI skills to extract mathematical models from elite repositories without corrupting the MARSLib IO Abstraction.</p>\n    </a>\n\n    <a href="/MARSLib/docs/tutorials/elite/uploader" class="tutorial-card">\n      <span class="card-tag">TELEMETRY</span>\n      <h3>Automated Log Uploader</h3>\n      <p>Configure MARSLib\'s asynchronous daemon thread to automatically upload AdvantageKit hardware logs directly to GitHub.</p>\n    </a>\n  </div>\n</main>\n'}}),d=[];function p(t){return(0,r.jsx)(c,{})}function u(t={}){const{wrapper:a}={...(0,o.R)(),...t.components};return a?(0,r.jsx)(a,{...t,children:(0,r.jsx)(p,{...t})}):p()}},28453:(t,a,e)=>{e.d(a,{R:()=>s,x:()=>i});var n=e(96540);const r={},o=n.createContext(r);function s(t){const a=n.useContext(o);return n.useMemo(function(){return"function"==typeof t?t(a):{...a,...t}},[a,t])}function i(t){let a;return a=t.disableParentContext?"function"==typeof t.components?t.components(r):t.components||r:s(t.components),n.createElement(o.Provider,{value:a},t.children)}}}]);